/* In-arena help and a pinned coach share the game's bindings and authored routes. */
(function(root){
  'use strict';
  const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const PAD={'attack:P':'X','attack:K':'Y','attack:H':'RB','attack:G':'D↓','attack:C':'VIEW',jump:'A',evade:'B',guard:'LT',power:'RT',wheel:'LB',utility:'D→',coat:'D←',aim:'R3',balloon:'L3',target:'D↑',pause:'START'};
  function placement(token){const family=root.CombatLab.MOVES[root.CombatLab.BASE[token]]?.elementFamily?.toLowerCase();if(['earth','fire','water'].includes(family))return {bank:'elements',element:family,page:/^[a-i]$/.test(token)?'more':'core',label:'Elements · '+family};if(token==='0')return {bank:'infuse',label:'Infuse'};if(['S','T','R','W','N','D','Z','V','E','L','Q','O'].includes(token))return {bank:'powers',label:'Powers'};if(['F','B','J'].includes(token))return {bank:'tools',label:'Tools'};return {bank:'fight',label:'Fight'};}
  class FieldGuide{
    constructor(options){Object.assign(this,options);this.dialog=document.getElementById('field-guide');this.previousPause=null;this.tab='controls';this.pinned=true;this.group='All';this.query='';this.routeId=this.getCoach().route.id;this.last='';this.lastCoach='';
      document.querySelectorAll('[data-field-open]').forEach(b=>b.addEventListener('click',()=>this.open(b.dataset.fieldOpen)));
      document.getElementById('field-close').addEventListener('click',()=>this.close());this.dialog.addEventListener('cancel',e=>{e.preventDefault();this.close();});this.dialog.addEventListener('close',()=>this.restore());
      document.querySelectorAll('[data-field-tab]').forEach(b=>b.addEventListener('click',()=>this.chooseTab(b.dataset.fieldTab)));
      document.getElementById('field-coach-toggle').addEventListener('click',()=>{this.pinned=!this.pinned;this.update();document.getElementById('arena').focus({preventScroll:true});});
      document.getElementById('field-coach-edit').addEventListener('click',()=>this.open('combos'));
      document.getElementById('field-coach-next').addEventListener('click',()=>{const c=this.getCoach();if(c.progress>=c.route.seq.length)this.open('combos');else{this.prepareControls(placement(c.route.seq[c.progress]));document.getElementById('arena').focus({preventScroll:true});}});
      document.getElementById('field-search').addEventListener('input',e=>{this.query=e.target.value;this.routes();});
      document.getElementById('field-group').innerHTML=['All',...new Set(root.CombatLab.ROUTES.map(r=>r.group))].map(g=>'<option value="'+esc(g)+'">'+esc(g)+'</option>').join('');
      document.getElementById('field-group').addEventListener('change',e=>{this.group=e.target.value;this.routes();});
      document.getElementById('field-pin').addEventListener('click',()=>{this.selectRoute(this.routeId);this.prepareControls(placement(this.getCoach().route.seq[0]));this.pinned=true;this.close();this.update();});
      document.getElementById('field-watch').addEventListener('click',()=>{if(this.world.run.active)return;this.selectRoute(this.routeId);this.pinned=true;this.close();this.awaken();this.setPaused(false);this.world.watch(this.routeId);this.syncMode();});
      document.getElementById('field-manual').addEventListener('click',()=>{this.world.setAssist('manual');this.syncMode();this.savePreferences();this.controls();});
      document.getElementById('field-show-flow').addEventListener('click',()=>{this.setBank('flow');this.close();});
      document.getElementById('field-rebind').addEventListener('click',()=>{this.close();document.getElementById('controls').click();});
      document.getElementById('field-interact').addEventListener('click',()=>{if(!this.isPaused()&&!this.world.run.blocked()){this.awaken();this.world.useArena();document.getElementById('arena').focus({preventScroll:true});}});
      this.chooseTab('controls');this.routes();this.update();
    }
    key(action){return this.bindings.device.startsWith('Gamepad')&&PAD[action]?PAD[action]:this.bindings.shortcut(action);}
    token(token){return this.bindings.bindings['attack:'+token]?this.key('attack:'+token):(root.CombatLab.KEY[token]||'Elements');}
    sequence(route,progress=0){return route.seq.split('').map((t,i)=>'<kbd class="'+(i<progress?'done':i===progress?'next':'')+'" title="'+esc(root.CombatLab.MOVES[route.steps[i]].name)+'">'+esc(this.token(t))+'</kbd>').join('<span>›</span>');}
    open(tab='controls'){if(this.world.run.blocked()||document.getElementById('controls-modal').open||document.getElementById('power-wheel-dialog').open)return false;if(!this.dialog.open){this.previousPause=this.isPaused();this.awaken();this.clearInputs();this.setPaused(true);document.getElementById('pause-overlay').hidden=true;this.dialog.showModal();}document.getElementById('field-menu-panel').hidden=true;document.getElementById('field-menu-toggle').setAttribute('aria-expanded','false');this.routeId=this.getCoach().route.id;this.chooseTab(tab);this.controls();this.routes();this.worldPanel();return true;}
    close(){if(this.dialog.open)this.dialog.close();this.restore();}
    restore(){if(this.dialog.open||this.previousPause===null)return;const value=this.previousPause;this.previousPause=null;this.clearInputs();this.setPaused(value);}
    chooseTab(name){this.tab=['controls','combos','world','style','boss'].includes(name)?name:'controls';document.querySelectorAll('[data-field-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.fieldTab===this.tab)));document.querySelectorAll('[data-field-panel]').forEach(p=>p.hidden=p.dataset.fieldPanel!==this.tab);}
    controls(){const labels=root.CombatPlayUI.actionLabels(this.world),rows=[['attack:P',labels.P],['attack:K',labels.K],['attack:H',labels.H],['attack:U',labels.U],['attack:G',labels.G],['attack:C',labels.C],['jump','Jump'],['evade','Evade / timed recovery'],['guard','Hold block / tap parry'],['duck','Hold duck'],['anchor','Stretch anchor / fetch'],['cover','Take / leave cover'],['pickup','Pick up / drop object'],['machine','Use nearby switch'],['power',this.world.easyPowerKey?'Power: tap easy combo':'Power: tap / hold'],['utility','Element utility'],['wheel','Choose element'],['powerthrow','Clinch: hold, steer, release'],['aim','Toggle ground aim'],['coat','Coat selected element'],['attack:S','Elastic punch'],['attack:T','Whip kick'],['attack:R','Reel / catch'],['attack:0','Release primed fusion'],['balloon','Inflate / unroll'],['target','Switch target']];
      document.getElementById('field-bindings').innerHTML=rows.map(([a,label])=>'<div><kbd>'+esc(this.key(a))+'</kbd><span>'+esc(label)+'</span></div>').join('');document.getElementById('field-device').textContent=this.bindings.device;document.getElementById('field-shortcut').textContent=this.key('guide');document.getElementById('field-footer').textContent='Close × / Escape to return · '+this.key('guide')+' toggles the guide · '+this.key('coach')+' toggles your pinned coach.';
      document.getElementById('field-move-keys').textContent=['up','left','down','right'].map(a=>this.key(a)).join(' / ');
      const power=this.world.power.snapshot(),utility={fire:'Utility releases stored heat once you have 35 heat.',water:'Utility surfs wet ground. Steer with movement; attack to dismount.',earth:'Stand still + Utility raises a terrace. Move + Utility sends a physical ridge.',wind:'Utility dashes with wind. Redirect once in the air with your Wind redirect control.',lightning:'Utility launches with Rising voltage. Wet targets conduct electricity.',stretch:'Utility reels or catches an opponent. Follow with hands, knees or a throw.'};
      document.getElementById('field-power-hint').textContent=power.selected.toUpperCase()+' · '+this.key('power')+(this.world.easyPowerKey?' tap: contextual easy combo. ': ' tap: '+power.primary+' · hold: '+power.held+'. ')+this.key('utility')+': '+utility[power.selected]+' Choose another element with '+this.key('wheel')+'.';
      document.getElementById('field-easy-note').textContent=this.world.assistMode==='easy'?'Easy combos: '+this.key('attack:P')+' builds a chain; '+this.key('attack:K')+' sets up air; '+this.key('attack:H')+' finishes. Use Manual to follow the exact steps in the combo book.':'Manual: each press requests one move. Queue up to four follow-ups; land the opener before cancelling.';
      document.getElementById('field-manual').hidden=this.world.assistMode!=='easy';
    }
    routes(){const all=root.CombatLab.ROUTES,q=this.query.trim().toLowerCase(),matches=all.filter(r=>(this.group==='All'||r.group===this.group)&&(!q||(r.name+' '+r.note+' '+r.group+' '+r.seq.split('').map(t=>this.token(t)).join(' ')).toLowerCase().includes(q))),shown=matches.slice(0,24);
      document.getElementById('field-route-count').textContent=matches.length+' routes'+(matches.length>24?' · showing first 24, filter to find more':'');
      document.getElementById('field-route-list').innerHTML=shown.map(r=>'<button type="button" data-field-route="'+r.id+'" aria-pressed="'+(r.id===this.routeId)+'"><strong>'+esc(r.name)+'</strong><small>'+esc(r.group)+' · '+r.seq.length+' moves</small><span class="field-sequence">'+this.sequence(r)+'</span></button>').join('')||'<p>No routes match. Try another category or move name.</p>';
      document.querySelectorAll('[data-field-route]').forEach(b=>b.addEventListener('click',()=>{this.routeId=b.dataset.fieldRoute;this.routes();document.querySelector('[data-field-route="'+this.routeId+'"]').focus();}));const route=all.find(r=>r.id===this.routeId)||all[0];document.getElementById('field-route-name').textContent=route.name;document.getElementById('field-route-note').textContent=route.note;document.getElementById('field-route-steps').innerHTML=route.steps.map((id,i)=>'<li><kbd>'+esc(this.token(route.seq[i]))+'</kbd> '+esc(root.CombatLab.MOVES[id].name)+'</li>').join('');document.getElementById('field-watch').disabled=this.world.run.active;
    }
    worldPanel(){const w=this.world,arena=w.yard.layout;document.getElementById('field-world-title').textContent=arena.name;document.getElementById('field-world-note').textContent=arena.story||arena.subtitle;document.getElementById('field-landmarks').innerHTML=(arena.features||['Break furniture with real impacts.','Use solid cover to block projectiles.','Retrieve loose objects with stretching.']).map(s=>'<li>'+esc(s)+'</li>').join('');
      const entries=root.CombatJournal.ENTRIES.filter(e=>e.arena===w.arenaId);document.getElementById('journal-count').textContent=w.journal.seen.size+' / '+root.CombatJournal.ENTRIES.length;document.getElementById('journal-entries').innerHTML=entries.map(e=>'<article><small>'+(w.journal.seen.has(e.id)?'DISCOVERED':'UNDISCOVERED · WALK TO THE BRASS MARKER')+'</small><h4>'+esc(e.title)+'</h4><p>'+esc(w.journal.seen.has(e.id)?e.text:'Near '+(e.x<0?'the west':'the east')+' side, '+(e.z<0?'toward the back':'toward the entrance')+'.')+'</p></article>').join('');
      document.getElementById('field-world-keys').textContent=this.key('pickup')+' pick up · '+this.key('anchor')+' fetch / anchor · '+this.key('cover')+' cover · '+this.key('machine')+' switch';
      document.getElementById('field-arenas').innerHTML=Object.entries(root.CombatArenas.ARENAS).map(([id,a])=>'<button data-field-arena="'+id+'" aria-pressed="'+(id===w.arenaId)+'" '+(w.run.active?'disabled':'')+'>'+esc(a.name)+'</button>').join('');document.querySelectorAll('[data-field-arena]').forEach(b=>b.addEventListener('click',()=>{if(w.run.active||b.dataset.fieldArena===w.arenaId)return;w.setArena(b.dataset.fieldArena);this.syncMode();this.savePreferences();this.worldPanel();}));
    }
    update(){const w=this.world,coach=this.getCoach(),r=coach.route,expanded=document.querySelector('.play-area').classList.contains('expanded');document.getElementById('field-coach').hidden=!expanded||!this.pinned||(w.run.blocked()||w.boss.blocked());document.getElementById('field-coach-toggle').setAttribute('aria-pressed',String(this.pinned));document.getElementById('field-shortcut').textContent=this.key('guide');
      const stamp=r.id+':'+coach.progress+':'+this.bindings.revision+':'+this.bindings.device+':'+w.assistMode;if(stamp!==this.lastCoach){this.lastCoach=stamp;document.getElementById('field-coach-name').textContent=r.name;document.getElementById('field-coach-sequence').innerHTML=this.sequence(r,coach.progress);document.getElementById('field-coach-state').textContent=w.assistMode==='easy'?'Easy mode · use Manual for these steps':coach.progress===r.seq.length?'CONNECTED ✓':coach.progress+' / '+r.seq.length+' · NEXT '+this.token(r.seq[coach.progress])+' · '+root.CombatLab.MOVES[r.steps[coach.progress]].name;}
      const next=document.getElementById('field-coach-next');next.textContent=coach.progress>=r.seq.length?'Choose another combo':'Show next buttons · '+placement(r.seq[coach.progress]).label;next.disabled=w.run.blocked();
      const near=w.yard.gadgets.nearest(w.player),item=w.yard.candidate(w.player,1.7),available=near&&near.d<=1.7;document.getElementById('field-interact').hidden=!available||w.over;document.getElementById('field-interact').disabled=this.isPaused()||w.run.blocked()||!!w.player.action||w.player.held||w.player.down>0||w.player.stunned>0||!!w.grapple||!!w.tether||!!w.player.balloon;document.getElementById('field-interact').textContent=this.key('machine')+' · '+(w.arenaId==='canal'?'Turn sluice wheel':'Use control post');
      document.getElementById('field-world-chip').textContent=w.yard.layout.name+(available?' · SWITCH NEARBY':item?' · '+this.key('pickup')+' '+item.name:'');
      const state=this.bindings.revision+':'+this.bindings.device+':'+w.arenaId+':'+w.assistMode+':'+w.journal.seen.size;if(this.dialog.open&&state!==this.last){this.controls();this.routes();this.worldPanel();}this.last=state;
    }
  }
  root.CombatFieldGuide={FieldGuide,placement};if(typeof module!=='undefined'&&module.exports)module.exports=root.CombatFieldGuide;
})(typeof window!=='undefined'?window:globalThis);
